from __future__ import print_function
from builtins import str
from builtins import object
import csv
import json
import os
from datetime import datetime
import re
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.parameters import Parameters
from taf.ul.trs_e2e_fw.lib.utils.exception.alarms_exception import AlarmShouldNotExistException, \
    AlarmNotFoundException, AllAlarmOccurencesNotFoundException, AlarmNotFoundInRise, \
    AlarmRiseValidationFailed, UnexpectedAlarmsFoundException, MoreThanRequiredAlarmsFound
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.resource_file import get_resource_file

logger = BackgroundLogger.Instance()


class AlarmsVerification(object):
    def __init__(self):
        self.parameters = Parameters()

    def verify_alarm_exists_and_validate_with_rise(self, alarm_object_list,
                                                   check_unexpected_alarms,
                                                   prev_alarms,
                                                   expected_alarms, faultid,
                                                   occurrences, should_exist,
                                                   alias, interface, alarm_id=""):
        unexpected_alarms = None
        if check_unexpected_alarms:
            unexpected_alarms = self._get_unexpected_alarms(alarm_object_list, prev_alarms, expected_alarms, interface,
                                                            faultid, alarm_id)
        found_occurences = self._verify_alarm_exists(alarm_object_list, faultid, alarm_id)
        rise_alarm_found, rise_validation_pass = None, None
        if faultid is not None:
            rise_alarm_found, rise_validation_pass =\
                self._verify_alarm_against_rise(alarm_object_list, faultid, interface,
                                                alias)
        self._raise_exceptions(should_exist, found_occurences,
                               occurrences, rise_alarm_found,
                               rise_validation_pass, check_unexpected_alarms,
                               unexpected_alarms, faultid, alarm_id)

    def _verify_alarm_exists(self, alarms_list, faultid=None, alarmid=None):
        # unexpected_alarms = self._get_unexpected_alarms(alarms_list, faultid, expected_alarms)
        found_occurences = self._get_occurences(alarms_list, faultid, alarmid)
        # self._raise_exceptions(faultid, should_exist, found_occurences, occurrences)
        return found_occurences

    def _get_occurences(self, alarms_list, faultid=None, alarmid=None):

        found_occurences = 0
        if faultid:
            id_key = 'FAULT ID'
            id_val = faultid
        else:
            id_key = 'ALARM ID'
            id_val = alarmid

        if id_key:

            self.alarm_details = list()
            for alarm_obj in alarms_list:
                # if int(alarm_obj['FAULT ID']) == int(faultid):
                logger.debug("******** faultID of alarm object is {} and given fault_id is {}"
                             "".format(alarm_obj[id_key], id_val))
                if alarm_obj[id_key] and alarm_obj[id_key] != 'N/A':
                    if int(alarm_obj[id_key]) == int(id_val):
                        found_occurences += 1
                        self.alarm_details.append(alarm_obj)

            print("alarms details {}".format(self.alarm_details))
        logger.debug("Alarm occurences :: {}".format(found_occurences))
        # print("alarms details {}".format(self.alarm_details))
        return found_occurences

    def _raise_exceptions(self, should_exist, found_occurences,
                          req_occurrences, rise_alarm_found,
                          rise_validation_status, check_unexpected_alarms,
                          unexpected_alarms, faultid=None, alarmid=None):

        id_key = alarmid if alarmid else faultid

        if check_unexpected_alarms and len(unexpected_alarms) > 0:
            raise UnexpectedAlarmsFoundException('Alarms {}'.format(
                unexpected_alarms))

        if id_key is not None:
            if should_exist is False:
                if found_occurences > 0:
                    raise AlarmShouldNotExistException('Alarms {}'.format(faultid))
            else:
                if found_occurences == 0:
                    raise AlarmNotFoundException
                elif found_occurences >= req_occurrences:
                    if faultid:
                        if rise_alarm_found is False:
                            raise AlarmNotFoundInRise
                        else:
                            if rise_validation_status is False:
                                raise AlarmRiseValidationFailed
                            else:
                                logger.debug('Rise Validation Success')
                    elif alarmid:
                        logger.debug("Verifying alarm id against rise.csv is skipped.")
                    if found_occurences > req_occurrences:
                        logger.warn('More Alarms {} found than expected {}'.format(found_occurences, req_occurrences))
                        raise MoreThanRequiredAlarmsFound
                elif found_occurences < req_occurrences:
                    raise AllAlarmOccurencesNotFoundException('Expected: {}, Found: {}'.format(req_occurrences,
                                                                                               found_occurences))

    def _get_params_from_alarm_obj(self, alarms_object):
        alarm_faultid = alarms_object['FAULT ID']
        alarm_id = alarms_object['ALARM ID']
        alarm_name = alarms_object['TEXT']
        alarm_faultname = alarms_object['FAULT NAME']
        logger.debug("*** alarm_faultid is {} ".format(alarm_faultid))
        logger.debug("*** alarm_faultname is {} ".format(alarm_faultname))
        logger.debug("*** alarm_id is {} ".format(alarm_id))
        logger.debug("*** alarm_name is {} ".format(alarm_name))
        return alarm_faultid, alarm_faultname, alarm_id, alarm_name

    def convert_date_format(self, datestring, interface):
        if interface == 'netact':
            ret = datetime.strptime(datestring[0:-5], '%Y-%m-%dT%H:%M:%S.%f')
        if interface == 'cu':
            ret = datetime.strptime(datestring[0:-6].split('.')[0], '%Y-%m-%dT%H:%M:%S')
        if interface == 'vdu':
            ret = datetime.strptime(datestring[0:-6].split('.')[0], '%Y-%m-%dT%H:%M:%S')
        return ret.strftime("%d/%m/%Y, %H:%M:%S")

    def write_alarms_to_file(self, file_name, alarm_objects_list):
        alarms_file_name = 'execution_logs/{}'.format(file_name)
        if not os.path.exists(os.path.dirname(alarms_file_name)):
            os.makedirs(os.path.dirname(alarms_file_name))
        with open(alarms_file_name, 'a') as alarms_file:
            logger.debug("Writing alarms to {}".format(alarms_file_name))
            alarms_file.write('\n\n===============================================\n\n')
            json.dump(alarm_objects_list, alarms_file)

    def _get_unexpected_alarms(self, alarm_object_list, alarms_for_comparison, expected_alarms, interface, given_faultid=None, given_alarmid=None):
        if expected_alarms is None:
            expected_alarms = []
        if given_faultid is not None:
            expected_alarms.append(int(given_faultid))
            id_key = 'FAULT ID'
        else:
            expected_alarms.append(int(given_alarmid))
            id_key = 'ALARM ID'

        if alarms_for_comparison:
            cur_fault_ids = [alarm[id_key] for alarm in alarm_object_list if
                             alarm[id_key] not in expected_alarms]
            logger.info('cur_fault_ids: {}'.format(cur_fault_ids))
            past_fault_ids =\
                [alarm[id_key] for alarm in alarms_for_comparison if
                 alarm[id_key] not in expected_alarms]
            logger.info('past_fault_ids: {}'.format(past_fault_ids))
            unexpected_alarms = [f_id for f_id in cur_fault_ids if
                                 f_id not in past_fault_ids]
        else:
            unexpected_alarms = [alarm[id_key] for alarm in alarm_object_list
                                 if alarm[id_key] not in expected_alarms]
        return unexpected_alarms

    def _verify_alarm_against_rise(self, alarm_object_list, faultid, interface, alias):
        rise_alarm_found = False
        rise_validation_pass = True
        rise_csv = get_config_variable(['rise_csv'])
        rise_header_fields = get_config_variable(['rise_header_fields'])
        for alarm_obj in alarm_object_list:
            alarm_faultid, alarm_faultname, alarm_id, alarm_name =\
                self._get_params_from_alarm_obj(alarm_obj)
            if alarm_faultid and alarm_faultid != 'N/A':
                if int(faultid) == int(alarm_faultid):
                    logger.info('given faultid: {}, foundid: {}'.format(
                        faultid, alarm_faultid))
                    rise_csv = get_resource_file(rise_csv)
                    # rise_csv = os.path.join(self.config["config_path"],
                    #                         'rise.csv')
                    with open(rise_csv) as rise_fh:
                        reader = csv.DictReader(rise_fh,
                                                fieldnames=rise_header_fields)
                        for rise_row in reader:
                            alarm_rise_match = re.search(r'^-?\s*{}:\s*.*\n?'.format(alarm_faultid),
                                                         rise_row['Fault ID and Fault ID Name'])
                            # At time it is observed that header in rise.csv and header passed from
                            # testcase_variable.json is not matched, which will in-turn result in column mismatch.
                            # Below debug statements will help us to know if headers mentioned in
                            # testcase_variable.json are in sync with underlying rise.csv
                            if 'Fault ID and Fault ID Name' in rise_row.get('Fault ID and Fault ID Name'):
                                logger.debug("#### 'Fault ID and Fault ID Name' is mapped to {}".format(rise_row['Fault ID and Fault ID Name']))
                                logger.debug("#### 'Fault name' is mapped to {}".format(rise_row['Fault name']))
                                logger.debug("#### 'Reported alarms' is mapped to {}".format(rise_row['Reported alarms']))
                                logger.debug("####'Reported alarms description' is mapped to {}".format(
                                    rise_row['Reported alarms description']))
                            if alarm_rise_match is not None:
                                logger.debug('Rise match found')
                                logger.debug('alarm_faultid: {}'.format(alarm_faultid))
                                logger.debug('RISE faultid_and_name: {}'.format(
                                    rise_row['Fault ID and Fault ID Name']), '\n')
                                rise_alarm_found = True
                                logger.debug("*** alarm id {} and alarm name {} to be verified against "
                                             "rise".format(alarm_id, alarm_name))
                                rise_validation_pass = self._verify_alarmname_in_rise_reported_alarms(
                                    alarm_id, alarm_name, rise_row, rise_validation_pass, interface, alias)
                                rise_validation_pass = self._verify_faultname_in_rise(
                                    alarm_faultname, rise_row, rise_validation_pass)
                                return rise_alarm_found, rise_validation_pass
        return rise_alarm_found, False

    def _verify_faultname_in_rise(self, alarm_faultname, rise_row, rise_validation_pass):
        rise_fault_name = rise_row['Fault name']
        logger.debug('Fault_name: {}'.format(alarm_faultname))
        logger.debug('RISE fault_name: {}'.format(rise_fault_name), '\n')
        if '$' not in rise_fault_name:  # If strings like $unit exist ignore this column
            if alarm_faultname.strip() != rise_fault_name.strip():
                logger.debug("Rise validation failed for faultName.\t\t\nADMIN:{0}\t\t\nRISE:{1}"
                             .format(alarm_faultname, rise_fault_name))
                rise_validation_pass = False
        return rise_validation_pass

    def _verify_alarmname_in_rise_reported_alarms(self, alarm_id,
                                                  alarm_name, rise_row,
                                                  rise_validation_pass, interface, alias):
        param_path = 'FMCADM-1:actCategoryAlarms'
        if interface == 'cu':
            actCategoryAlarms = self.parameters.get_parameter(param_path=param_path, alias=alias)
        else:
            actCategoryAlarms = None
        logger.info('actCategoryAlarms: {}'.format(actCategoryAlarms))
        rise_reported_alarms = rise_row['Reported alarms']
        rise_reported_alarms_desc = rise_row['Reported alarms description']
        logger.debug('alarm_id: {}'.format(alarm_id))
        logger.debug('alarm_name: {}'.format(alarm_name))
        logger.debug('RISE Reported alarms: {}'.format(rise_reported_alarms), '\n')
        logger.debug('RISE Reported alarms desc: {}'.format(rise_reported_alarms_desc), '\n')
        if actCategoryAlarms is not None:
            rise_reported_alarms_for_true = re.findall(r'true\).*?({}\s*{}).*?if'.format(
                alarm_id, alarm_name), rise_reported_alarms_desc, (re.DOTALL | re.I))
            rise_reported_alarms_for_false = re.findall(r'false\).*?({}\s*{}).*?'.format(
                alarm_id, alarm_name), rise_reported_alarms_desc, (re.DOTALL | re.I))
            if len(rise_reported_alarms_for_true) != 0 or len(rise_reported_alarms_for_false) != 0:
                rise_validation_pass = getattr(self, '_verify_rise_actcategoryalarms_{}'.format(
                    str(actCategoryAlarms).lower()))(actCategoryAlarms, alarm_name,
                                                     rise_reported_alarms_for_false,
                                                     rise_reported_alarms_for_true,
                                                     rise_validation_pass)
            else:
                rise_validation_pass = self._verify_rise_without_actcategoryalarms(
                    alarm_name, alarm_id, rise_reported_alarms, rise_validation_pass)
        else:
            rise_validation_pass = self._verify_rise_without_actcategoryalarms(
                alarm_name, alarm_id, rise_reported_alarms, rise_validation_pass)
        return rise_validation_pass

    def _verify_rise_without_actcategoryalarms(self, alarm_name, alarm_id,
                                               rise_reported_alarms, rise_validation_pass):
        if '$' not in rise_reported_alarms:
            rise_reported_alarms_matched = re.findall(r'.*?({}\s*{}).*?'.format(alarm_id,
                                                                                alarm_name),
                                                      rise_reported_alarms, (re.DOTALL | re.I))
            if len(rise_reported_alarms_matched) == 0:
                rise_validation_pass = False
                logger.warn('alarm name {} not found in RISE reported alarms'.format(
                    alarm_name))
            return rise_validation_pass
        else:
            logger.info('Ignored reported alarms with $')

    def _verify_rise_actcategoryalarms_true(self, actCategoryAlarms, admin_alarm_name,
                                            rise_reported_alarms_for_false,
                                            rise_reported_alarms_for_true, rise_validation_pass):
        if len(rise_reported_alarms_for_true) == 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match not found in RISE true category'
                        .format(actCategoryAlarms, admin_alarm_name))
        if len(rise_reported_alarms_for_false) != 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match found in RISE false category'
                        .format(actCategoryAlarms, admin_alarm_name))
        logger.info('actCategoryAlarms {}, alarm {} match found in RISE true category'
                    .format(actCategoryAlarms, admin_alarm_name))
        return rise_validation_pass

    def _verify_rise_actcategoryalarms_false(self, actCategoryAlarms, admin_alarm_name,
                                             rise_reported_alarms_for_false,
                                             rise_reported_alarms_for_true, rise_validation_pass):
        if len(rise_reported_alarms_for_false) == 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match not found in RISE false category'
                        .format(actCategoryAlarms, admin_alarm_name))
        if len(rise_reported_alarms_for_true) != 0:
            rise_validation_pass = False
            logger.warn('actCategoryAlarms {}, alarm {} match found in RISE true category'
                        .format(actCategoryAlarms, admin_alarm_name))
        logger.info('actCategoryAlarms {}, alarm {} match found in RISE false category'
                    .format(actCategoryAlarms, admin_alarm_name))
        return rise_validation_pass
